for root,dirs,files in os.walk(D):
    for f in sorted(files):
        p=os.path.join(root,f); rel=os.path.relpath(p,D)
        if rel=='FUENTES.txt': continue
        b=os.path.getsize(p)
        if f in m: url,desc=m[f]
        elif rel.startswith('scripts/'): url,desc='ELABORACIÓN PROPIA','Script usado (Python). Ver encabezado del archivo'
        elif rel.startswith('derivados/texto_'): url,desc='ELABORACIÓN PROPIA (texto extraído)','Texto plano extraído de: '+f.replace('texto_','')
        elif rel.startswith('derivados/anexo8894'): url,desc='ELABORACIÓN PROPIA (imagen extraída y rotada)','Página del Anexo 1 de la Ordenanza 8894 (Plan Director AySA San Isidro 2016), del PDF BO_MSI #962'
        elif rel.startswith('work/'): url,desc='http://crt.sectigo.com/SectigoPublicServerAuthenticationCADVR36.crt (certificado) / armado propio','Herramienta TLS: certificado intermedio Sectigo DV R36 para validar www.aysa.com.ar (la verificación TLS siguió activa)'
        else: url,desc='?','?'
        lines.append(f'{rel} | {b} | {url} | {F} | {desc}')
